WITH fx AS (SELECT CAST(json_extract_string(state,'$.rate') AS DECIMAL(18,6)) AS r, CAST(json_extract_string(state,'$.date') AS DATE) AS d FROM objects WHERE object_type = 'fx_rate' AND json_extract_string(state,'$.base') = 'EUR' AND json_extract_string(state,'$.quote') = 'PLN'), rate AS (SELECT COALESCE((SELECT r FROM fx WHERE d <= {{period_to}} ORDER BY d DESC LIMIT 1), (SELECT r FROM fx ORDER BY d LIMIT 1)) AS r), ic AS (SELECT DISTINCT root_event_id FROM objects WHERE object_type = 'purchase_invoice'), p AS (SELECT a.object_id AS acc, json_extract_string(a.state,'$.code') AS code, json_extract_string(a.state,'$.name') AS account, CAST(json_extract_string(o.state,'$.date') AS DATE) AS d, json_extract_string(o.state,'$.side') AS side, CASE WHEN json_extract_string(o.state,'$.currency') = 'EUR' THEN CAST(json_extract(o.state,'$.amount') AS BIGINT) ELSE CAST(round(CAST(json_extract(o.state,'$.amount') AS BIGINT) / (SELECT r FROM rate)) AS BIGINT) END AS eur FROM objects o JOIN objects a ON json_extract_string(o.state,'$.account') = a.object_id WHERE o.object_type = 'posting' AND a.object_type = 'account' AND CAST(json_extract_string(o.state,'$.date') AS DATE) <= {{period_to}} AND NOT (o.root_event_id IN (SELECT root_event_id FROM ic) AND json_extract_string(a.state,'$.type') <> 'tax')), t AS (SELECT code, account, string_agg(DISTINCT acc, ',' ORDER BY acc) AS o, COALESCE(SUM(CASE WHEN side = 'debit' THEN eur ELSE -eur END) FILTER (WHERE d < {{year_from}}), 0) AS bo, COALESCE(SUM(eur) FILTER (WHERE side = 'debit' AND d >= {{period_from}}), 0) AS pd, COALESCE(SUM(eur) FILTER (WHERE side = 'credit' AND d >= {{period_from}}), 0) AS pc, COALESCE(SUM(eur) FILTER (WHERE side = 'debit' AND d >= {{year_from}}), 0) AS yd, COALESCE(SUM(eur) FILTER (WHERE side = 'credit' AND d >= {{year_from}}), 0) AS yc FROM p GROUP BY 1, 2), s AS (SELECT COALESCE(SUM(bo), 0) AS b, COALESCE(SUM(pd) - SUM(pc), 0) AS pn, COALESCE(SUM(yd) - SUM(yc), 0) AS yn FROM t), rows_ AS (SELECT code, account, o, bo, pd, pc, yd, yc FROM t WHERE bo <> 0 OR yd <> 0 OR yc <> 0 UNION ALL SELECT 'CTA', 'Translation difference', '', -b, GREATEST(-pn, 0), GREATEST(pn, 0), GREATEST(-yn, 0), GREATEST(yn, 0) FROM s WHERE b <> 0 OR pn <> 0 OR yn <> 0) SELECT code, account, GREATEST(bo, 0) AS opening_debit, GREATEST(-bo, 0) AS opening_credit, pd AS debit, pc AS credit, yd AS ytd_debit, yc AS ytd_credit, GREATEST(bo + yd - yc, 0) AS closing_debit, GREATEST(-(bo + yd - yc), 0) AS closing_credit, o AS _of FROM rows_ ORDER BY code
